SET client_encoding = 'UTF8';
SET search_path TO pevc_week13;

\copy (SELECT table_name, row_count FROM (SELECT 'week13_selected_companies' AS table_name, count(*)::text AS row_count FROM week13_selected_companies UNION ALL SELECT 'week13_chapter_locator', count(*)::text FROM week13_chapter_locator UNION ALL SELECT 'week13_auto_evidence_candidates', count(*)::text FROM week13_auto_evidence_candidates UNION ALL SELECT 'week13_investor_profile', count(*)::text FROM week13_investor_profile UNION ALL SELECT 'week13_investor_type_rules', count(*)::text FROM week13_investor_type_rules UNION ALL SELECT 'week13_event_summary', count(*)::text FROM week13_event_summary UNION ALL SELECT 'week13_old_new_crosscheck', count(*)::text FROM week13_old_new_crosscheck UNION ALL SELECT 'week13_company_progress', count(*)::text FROM week13_company_progress UNION ALL SELECT 'week13_manual_review_queue', count(*)::text FROM week13_manual_review_queue UNION ALL SELECT 'week13_weekly_plan', count(*)::text FROM week13_weekly_plan UNION ALL SELECT 'week13_validation_summary', count(*)::text FROM week13_validation_summary) q ORDER BY table_name) TO 'database/postgresql_week13_table_counts.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');

\copy (SELECT '数据库类型' AS item, 'PostgreSQL临时实例' AS value, '验证第十三周扩样结果可以重复导入和查询' AS source_note UNION ALL SELECT '导入表数量', count(*)::text, 'pevc_week13 schema' FROM information_schema.tables WHERE table_schema='pevc_week13' UNION ALL SELECT '导入总行数', sum(row_count)::text, '11张派生表合计' FROM (SELECT count(*) AS row_count FROM week13_selected_companies UNION ALL SELECT count(*) FROM week13_chapter_locator UNION ALL SELECT count(*) FROM week13_auto_evidence_candidates UNION ALL SELECT count(*) FROM week13_investor_profile UNION ALL SELECT count(*) FROM week13_investor_type_rules UNION ALL SELECT count(*) FROM week13_event_summary UNION ALL SELECT count(*) FROM week13_old_new_crosscheck UNION ALL SELECT count(*) FROM week13_company_progress UNION ALL SELECT count(*) FROM week13_manual_review_queue UNION ALL SELECT count(*) FROM week13_weekly_plan UNION ALL SELECT count(*) FROM week13_validation_summary) s UNION ALL SELECT '首批扩样公司数', count(*)::text, 'week13_selected_companies' FROM week13_selected_companies UNION ALL SELECT '页码化文本总页数', sum(page_count::integer)::text, 'week13_selected_companies.page_count' FROM week13_selected_companies UNION ALL SELECT 'Auto候选记录数', count(*)::text, '含保留与规则排除记录' FROM week13_auto_evidence_candidates UNION ALL SELECT '保留Auto候选数', count(*)::text, 'auto_status以保留开头' FROM week13_auto_evidence_candidates WHERE auto_status LIKE '保留%' UNION ALL SELECT '转让系统语境排除数', count(*)::text, 'auto_status以排除开头' FROM week13_auto_evidence_candidates WHERE auto_status LIKE '排除%' UNION ALL SELECT '去重投资主体候选数', count(*)::text, '仍需人工确认分类' FROM week13_investor_profile UNION ALL SELECT '人工复核队列数', count(*)::text, '优先核对低/中置信及转让/备案' FROM week13_manual_review_queue UNION ALL SELECT '旧定位页平均找回率', round(avg(NULLIF(old_page_recovery_rate,'')::numeric),4)::text, '定位一致性，不等同Gold准确率' FROM week13_old_new_crosscheck UNION ALL SELECT '已填写AMAC编码数', count(*)::text, '未披露保持空值' FROM week13_investor_profile WHERE coalesce(amac_filing_code,'') <> '' UNION ALL SELECT '已填写GP数', count(*)::text, '未披露保持空值' FROM week13_investor_profile WHERE coalesce(gp_name,'') <> '' UNION ALL SELECT '已填写LP结构数', count(*)::text, '未披露保持空值' FROM week13_investor_profile WHERE coalesce(lp_structure,'') <> '') TO 'database/postgresql_week13_disclosure.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');

\copy (SELECT event_type, candidate_records, companies_covered, high_confidence_records FROM week13_event_summary ORDER BY event_code) TO 'database/postgresql_week13_event_counts.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');
